using System.Text.Json; using Ct.Core; using Ct.Stu.Application; using Ct.Stu.Domain; using Ct.Stu.Infrastructure.Persistence; using Microsoft.EntityFrameworkCore;
namespace Ct.Stu.Infrastructure;
public sealed class StudentService(StuDbContext db) : IStudentQueries, IStudentCommands
{
    static StudentDetails Map(Student s)=>new(s.Id,s.StudentId,s.Name,s.AdmissionNumber,s.ApplicationNumber,s.DateOfBirth,s.DateOfAdmission,s.Email,s.Gender,s.Mobile,s.AadharNumber,s.Status,s.Enrollments,s.Contacts,s.Metadata);
    public async Task<StudentDetails> CreateAsync(CreateStudentRequest r,CancellationToken ct){var s=new Student{Id=Guid.NewGuid(),StudentId=r.StudentId,Name=r.Name,AdmissionNumber=r.AdmissionNumber,ApplicationNumber=r.ApplicationNumber,DateOfBirth=r.DateOfBirth,DateOfAdmission=r.DateOfAdmission,Email=r.Email,Gender=r.Gender,Mobile=r.Mobile,AadharNumber=r.AadharNumber,CreatedAt=DateTime.UtcNow,UpdatedAt=DateTime.UtcNow,Enrollments=JsonSerializer.Serialize(new[]{new{InstId="",CourseName=r.CourseName,CourseId=r.CourseId,TermName="",SectionName="",Branch=""}})};db.Students.Add(s);await db.SaveChangesAsync(ct);return Map(s);}
    public async Task<StudentDetails?> GetByIdAsync(Guid id,CancellationToken ct){var s=await db.Students.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,ct);return s is null?null:Map(s);}
    public async Task<PagedResult<StudentListItem>> GetAsync(string? studentId,bool activeOnly,bool tcOnly,int page,int pageSize,CancellationToken ct){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,500);var q=db.Students.AsNoTracking();if(!string.IsNullOrWhiteSpace(studentId))q=q.Where(x=>x.StudentId==studentId);if(activeOnly)q=q.Where(x=>x.Status==StudentStatus.Active);if(tcOnly)q=q.Where(x=>x.Status==StudentStatus.TransferCertificate);var total=await q.CountAsync(ct);var rows=await q.OrderBy(x=>x.Name).Skip((page-1)*pageSize).Take(pageSize).Select(x=>new StudentListItem(x.Id,x.StudentId,x.Name,x.Status,null,null,null)).ToListAsync(ct);return new(rows,page,pageSize,total);}
    public async Task<IReadOnlyList<StudentListItem>> GetAllAsync(bool includeRte,CancellationToken ct)=>await db.Students.AsNoTracking().OrderBy(x=>x.Name).Select(x=>new StudentListItem(x.Id,x.StudentId,x.Name,x.Status,null,null,null)).ToListAsync(ct);
    public async Task<IReadOnlyList<StudentFeeSummary>> GetFeeSummaryAsync(Guid? studentId,CancellationToken ct){var q=db.StudentFeeSummaries.AsNoTracking();if(studentId.HasValue)q=q.Where(x=>x.StudentPk==studentId);return await q.ToListAsync(ct);}
    async Task<bool> SetStatus(Guid id,StudentStatus status,CancellationToken ct){var s=await db.Students.SingleOrDefaultAsync(x=>x.Id==id,ct);if(s is null)return false;s.Status=status;s.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync(ct);return true;}
    public Task<bool> EnableAsync(Guid id,CancellationToken ct)=>SetStatus(id,StudentStatus.Active,ct);public Task<bool> DisableAsync(Guid id,CancellationToken ct)=>SetStatus(id,StudentStatus.Disabled,ct);public Task<bool> TcAsync(Guid id,CancellationToken ct)=>SetStatus(id,StudentStatus.TransferCertificate,ct);
    public async Task<StudentDetails?> UpdateAsync(Guid id,UpdateStudentRequest r,CancellationToken ct){var s=await db.Students.SingleOrDefaultAsync(x=>x.Id==id,ct);if(s is null)return null;s.Name=r.Name;s.Email=r.Email;s.Mobile=r.Mobile;s.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync(ct);return Map(s);}
}
